      if (syms.length === 0) continue
      options.push({ key: group.id, name: group.name, dot: resolveWatchlistGroupColor(group.color).dot, symbols: syms })
    }
    const ungrouped = entries.filter(e => !(e.group_ids?.length)).map(e => e.symbol)
